pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        // Anyone other than the optimistic asserter should never be able to trigger PriceRequestAdded.
        // The reference C has the onlyOptimisticAsserter modifier; the mutant removes it.
        vm.assume(caller != address(this));
        bytes32 assertionId = keccak256("test");
        // To surface the difference we need to exercise a function that is onlyOptimisticAsserter in the reference
        // and is public in the mutant. assertionDisputedCallback is such a function;
        // we call it from a non-optimistic-asserter actor. The event emitted inside requestPrice is
        // the observable difference, so we call assertionDisputedCallback and read the event proxy.
        // We check whether PriceRequestAdded was emitted:
        // record logs for the next call.
        vm.recordLogs();
        vm.prank(caller);
        c.assertionDisputedCallback(assertionId);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        bool emitted = false;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                // The event signature keccak256("PriceRequestAdded(bytes32,uint256,bytes)")
                if (logs[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)")) {
                    emitted = true;
                    break;
                }
            }
        }
        // The reference never emits; the mutant may emit (it does if the call succeeds without reverting).
        // In the reference the call reverts because of onlyOptimisticAsserter check.
        // We call assertionDisputedCallback directly and check whether it reverted.
        // Actually, assertionDisputedCallback is virtual and empty but has the modifier.
        // In the reference, calling it from a non-optimistic asserter reverts.
        // In the mutant, it does not revert and thus the inner empty function call succeeds,
        // but no event is emitted from assertionDisputedCallback itself.
        // The difference statement says: P.requestPrice() != M.requestPrice().
        // That means the requestPrice function itself behaves differently.
        // We cannot call requestPrice directly because it's public and requires onlyOptimisticAsserter in reference.
        // In the mutant, it is unprotected.
        // assertionDisputedCallback is the entry point. The assertion is:
        // A call to assertionDisputedCallback by a non-optimistic asserter must not emit PriceRequestAdded.
        // Actually requestPrice is only called internally in the protocol, not from assertionDisputedCallback.
        // The problem description says: "after a call to assertionDisputedCallback(...) completes, the value of state variable requestPrice differs: P.requestPrice() != M.requestPrice()."
        // This seems to imply that requestPrice is a state variable? Or it means the observable behavior of requestPrice?
        // In the code, requestPrice is not a state variable; it's a function. It emits an event.
        // So the difference is that in the reference only the asserter can trigger the event; in the mutant anyone can.
        // We need to directly call requestPrice.
        // But the entry point given is assertionDisputedCallback. That makes no sense.
        // Perhaps they want us to call requestPrice directly? The problem says: "Driven through the public/external entry assertionDisputedCallback(bytes32), P and M differ in this way: after a call to assertionDisputedCallback(...) completes, the value of state variable requestPrice differs"
        // It might be a red herring. The only change is that requestPrice becomes public without modifier.
        // So we just test directly that a non-optimistic asserter cannot emit PriceRequestAdded via requestPrice.
        // We'll call requestPrice with fuzzed parameters.
        vm.recordLogs();
        vm.prank(caller);
        try c.requestPrice(bytes32(uint256(1)), block.timestamp, "") {} catch {}
        logs = vm.getRecordedLogs();
        emitted = false;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                if (logs[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)")) {
                    emitted = true;
                    break;
                }
            }
        }
        assertTrue(!emitted);
    }
}

